WITH seed (id, section, question, choices, answer_index, sort_order) AS (
  VALUES
  ('1f1cad2c-e6d5-4bd6-a817-000000000001'::uuid, 'Maxwell and Electromagnetic Theory', 'A static point charge generates:', '["an electric field only","a magnetic field only","constant electric and magnetic fields","an electromagnetic wave"]'::jsonb, 0, 1),
  ('1f1cad2c-e6d5-4bd6-a817-000000000002'::uuid, 'Maxwell and Electromagnetic Theory', 'A charge moving at constant velocity generates:', '["an electromagnetic wave","an electric field only","constant electric and magnetic fields","no field"]'::jsonb, 2, 2),
  ('1f1cad2c-e6d5-4bd6-a817-000000000003'::uuid, 'Maxwell and Electromagnetic Theory', 'Accelerated charges generate:', '["static fields only","a magnetic field only","no fields","two oscillating electric and magnetic fields that propagate through space"]'::jsonb, 3, 3),
  ('1f1cad2c-e6d5-4bd6-a817-000000000004'::uuid, 'Maxwell and Electromagnetic Theory', '"There are no magnetic monopoles" means that magnetic field lines are:', '["open","closed","radial","parallel"]'::jsonb, 1, 4),
  ('1f1cad2c-e6d5-4bd6-a817-000000000005'::uuid, 'Maxwell and Electromagnetic Theory', 'A time-varying electric field generates:', '["a static magnetic field","a static electric field","a time-varying magnetic field perpendicular to it and in phase with it","nothing"]'::jsonb, 2, 5),
  ('1f1cad2c-e6d5-4bd6-a817-000000000006'::uuid, 'Maxwell and Electromagnetic Theory', 'Maxwell concluded that:', '["time-varying, correlative electric and magnetic fields may propagate in space as a wave","a magnetic field is produced only by conduction current","electromagnetic waves need a material medium","electromagnetic waves are longitudinal"]'::jsonb, 0, 6),
  ('1f1cad2c-e6d5-4bd6-a817-000000000007'::uuid, 'Maxwell and Electromagnetic Theory', 'The origin of an electromagnetic wave is:', '["static charges","direct current","neutral atoms","oscillating electric charges"]'::jsonb, 3, 7),
  ('1f1cad2c-e6d5-4bd6-a817-000000000008'::uuid, 'Maxwell and Electromagnetic Theory', 'The speed of electromagnetic waves in vacuum is approximately:', '["3×10⁶ m/s","3×10⁸ m/s","3×10¹⁰ m/s","340 m/s"]'::jsonb, 1, 8),
  ('1f1cad2c-e6d5-4bd6-a817-000000000009'::uuid, 'Maxwell and Electromagnetic Theory', 'Electromagnetic waves are transverse because:', '["both fields oscillate perpendicular to the line of propagation","they need a medium","the fields oscillate along the line of propagation","they are slow"]'::jsonb, 0, 9),
  ('1f1cad2c-e6d5-4bd6-a817-000000000010'::uuid, 'Maxwell and Electromagnetic Theory', 'In vacuum, the energy of an electromagnetic wave is distributed:', '["entirely in the electric field","entirely in the magnetic field","equally between the electric and magnetic fields","in a 2:1 ratio"]'::jsonb, 2, 10),
  ('1f1cad2c-e6d5-4bd6-a817-000000000011'::uuid, 'Maxwell and Electromagnetic Theory', 'When an electromagnetic wave travels through a material medium, its speed:', '["increases","stays unchanged","becomes zero","is reduced according to the physical properties of the medium"]'::jsonb, 3, 11),
  ('1f1cad2c-e6d5-4bd6-a817-000000000012'::uuid, 'Maxwell and Electromagnetic Theory', 'Displacement current (Id) is proportional to the:', '["time rate of change of the magnetic field","time rate of change of the conduction current","time rate of change of the electric field","time rate of change of the polarization current"]'::jsonb, 2, 12),
  ('1f1cad2c-e6d5-4bd6-a817-000000000013'::uuid, 'Generating Electromagnetic Waves', 'The first scientist to generate electromagnetic waves (1887) was:', '["Maxwell","Hertz","Faraday","Marconi"]'::jsonb, 1, 13),
  ('1f1cad2c-e6d5-4bd6-a817-000000000014'::uuid, 'Generating Electromagnetic Waves', 'In Hertz''s experiment, a spark appears in the metal ring only if:', '["the ring has any diameter","it is connected to the transmitter by wires","the ring is completely closed","it has a specific diameter and the line separating its two ends is parallel to the line between the poles producing the spark"]'::jsonb, 3, 14),
  ('1f1cad2c-e6d5-4bd6-a817-000000000015'::uuid, 'Generating Electromagnetic Waves', 'Oscillation of free electrons in a conductor produces:', '["radio waves","X-rays","gamma rays","infrared waves"]'::jsonb, 0, 15),
  ('1f1cad2c-e6d5-4bd6-a817-000000000016'::uuid, 'Generating Electromagnetic Waves', 'Radio waves are generated by:', '["direct current in a wire","a charge moving at constant velocity","an accelerated electric charge in a conductor","static charges in a conductor"]'::jsonb, 2, 16),
  ('1f1cad2c-e6d5-4bd6-a817-000000000017'::uuid, 'Generating Electromagnetic Waves', 'A current-carrying wire radiates electromagnetic waves only when the current is:', '["direct","alternating","zero","constant"]'::jsonb, 1, 17),
  ('1f1cad2c-e6d5-4bd6-a817-000000000018'::uuid, 'Generating Electromagnetic Waves', 'In the electric dipole, when the emf reaches its maximum, the speed of the charges at the ends of the bars is:', '["maximum","constant","infinite","zero"]'::jsonb, 3, 18),
  ('1f1cad2c-e6d5-4bd6-a817-000000000019'::uuid, 'Oscillation Circuit and Antenna', 'The oscillation circuit consists of:', '["a coil of negligible resistance and a variable capacitor","a resistor and a capacitor","a transformer","a diode and a resistor"]'::jsonb, 0, 19),
  ('1f1cad2c-e6d5-4bd6-a817-000000000020'::uuid, 'Oscillation Circuit and Antenna', 'The resonance frequency of the oscillation circuit is given by:', '["fr = 2π√LC","fr = 1/(2π√LC)","fr = 1/(2πLC)","fr = √LC/2π"]'::jsonb, 1, 20),
  ('1f1cad2c-e6d5-4bd6-a817-000000000021'::uuid, 'Oscillation Circuit and Antenna', 'The antenna consists of:', '["one closed loop","a resistor and a capacitor","two separate metal wires connected to an alternating voltage source","a coil only"]'::jsonb, 2, 21),
  ('1f1cad2c-e6d5-4bd6-a817-000000000022'::uuid, 'Oscillation Circuit and Antenna', 'Transmission and reception of electromagnetic waves depend on:', '["the diameter of the antenna wire","the density of the antenna wire","both a and b","the oscillation circuit and the antenna"]'::jsonb, 3, 22),
  ('1f1cad2c-e6d5-4bd6-a817-000000000023'::uuid, 'Oscillation Circuit and Antenna', 'The power of the antenna in transmitting or receiving depends on:', '["the voltage supplied and the frequency of the signal","the colour of the wire","the mass of the antenna","the temperature only"]'::jsonb, 0, 23),
  ('1f1cad2c-e6d5-4bd6-a817-000000000024'::uuid, 'Oscillation Circuit and Antenna', 'The antenna has maximum signal energy when its length equals:', '["one wavelength","half the wavelength","twice the wavelength","any length"]'::jsonb, 1, 24),
  ('1f1cad2c-e6d5-4bd6-a817-000000000025'::uuid, 'Oscillation Circuit and Antenna', 'In a half-wave antenna:', '["voltage and current are maximum at the ends","voltage is minimum and current maximum at the ends","voltage is maximum at the ends and current is maximum at the middle (feeding point)","voltage and current are zero"]'::jsonb, 2, 25),
  ('1f1cad2c-e6d5-4bd6-a817-000000000026'::uuid, 'Oscillation Circuit and Antenna', 'Grounding one pole of the antenna makes it a:', '["quarter-wave antenna","full-wave antenna","eighth-wave antenna","no change"]'::jsonb, 0, 26),
  ('1f1cad2c-e6d5-4bd6-a817-000000000027'::uuid, 'Oscillation Circuit and Antenna', 'The receiver intensity increases when we touch the radio antenna because the antenna becomes:', '["twice as long","an eighth of a wavelength","a full wavelength","a quarter of a wavelength"]'::jsonb, 3, 27),
  ('1f1cad2c-e6d5-4bd6-a817-000000000028'::uuid, 'Oscillation Circuit and Antenna', 'The length of a grounded antenna equals:', '["λ/2","λ/4","λ","2λ"]'::jsonb, 1, 28),
  ('1f1cad2c-e6d5-4bd6-a817-000000000029'::uuid, 'Oscillation Circuit and Antenna', 'A tuning circuit has L = 6.4 μH and C = 1.9 pF. The frequency of the wave it receives is approximately:', '["4.56 MHz","456 MHz","45.6 MHz","4.56 GHz"]'::jsonb, 2, 29),
  ('1f1cad2c-e6d5-4bd6-a817-000000000030'::uuid, 'Oscillation Circuit and Antenna', 'The wavelength of the wave in the previous question is approximately:', '["6.6 m","66 m","0.66 m","660 m"]'::jsonb, 0, 30),
  ('1f1cad2c-e6d5-4bd6-a817-000000000031'::uuid, 'Oscillation Circuit and Antenna', 'The length of a half-wave antenna for a 200 MHz signal is:', '["7500 m","1.5 m","3 m","0.75 m"]'::jsonb, 3, 31),
  ('1f1cad2c-e6d5-4bd6-a817-000000000032'::uuid, 'Oscillation Circuit and Antenna', 'The length of a half-wave antenna for a 20 kHz signal is:', '["15000 m","7500 m","3750 m","750 m"]'::jsonb, 1, 32),
  ('1f1cad2c-e6d5-4bd6-a817-000000000033'::uuid, 'Oscillation Circuit and Antenna', 'The shortest antenna length needed to receive a 300 MHz signal is:', '["1 m","0.5 m","0.25 m","2 m"]'::jsonb, 2, 33),
  ('1f1cad2c-e6d5-4bd6-a817-000000000034'::uuid, 'Oscillation Circuit and Antenna', 'A tuning circuit with L = 0.5 μH receives a 500 kHz station. The required capacitance is approximately:', '["0.2 μF","0.2 pF","2 μF","2 nF"]'::jsonb, 0, 34),
  ('1f1cad2c-e6d5-4bd6-a817-000000000035'::uuid, 'Transmission and Reception Circuits', 'In the transmission device, the frequency of the induced current in the antenna coil equals:', '["twice the oscillation circuit frequency","half the oscillation circuit frequency","zero","the frequency of the signal in the oscillation circuit"]'::jsonb, 3, 35),
  ('1f1cad2c-e6d5-4bd6-a817-000000000036'::uuid, 'Transmission and Reception Circuits', 'In the reception circuit, resonance is reached by adjusting the:', '["resistance","capacitance of the capacitor","length of the wire","voltage"]'::jsonb, 1, 36),
  ('1f1cad2c-e6d5-4bd6-a817-000000000037'::uuid, 'Transmission and Reception Circuits', 'In detecting waves by their electric field, the electric field (Ey) of the wave:', '["induces an emf in a ring","produces heat","makes the charges oscillate in the antenna","stops the charges"]'::jsonb, 2, 37),
  ('1f1cad2c-e6d5-4bd6-a817-000000000038'::uuid, 'Transmission and Reception Circuits', 'The antenna used to detect waves by their magnetic field is:', '["a ring of conductive wire","a straight wire","a capacitor","a resistor"]'::jsonb, 0, 38),
  ('1f1cad2c-e6d5-4bd6-a817-000000000039'::uuid, 'Transmission and Reception Circuits', 'A loop antenna gives the best reception when its plane is:', '["parallel to the magnetic flux","at 45° to the flux","independent of direction","perpendicular to the magnetic flux direction"]'::jsonb, 3, 39),
  ('1f1cad2c-e6d5-4bd6-a817-000000000040'::uuid, 'Transmission and Reception Circuits', 'Mini-radio receivers pick up stations differently according to their direction because:', '["the wave frequency changes","the orientation of the loop plane relative to the magnetic flux changes","the wave amplitude is fixed","the wave speed changes"]'::jsonb, 1, 40),
  ('1f1cad2c-e6d5-4bd6-a817-000000000041'::uuid, 'Modulation', 'Modulation means conveying:', '["a high-frequency signal on a low-frequency wave","a signal without any wave","a low-frequency information signal over a high-frequency wave","a wave through a wire"]'::jsonb, 2, 41),
  ('1f1cad2c-e6d5-4bd6-a817-000000000042'::uuid, 'Modulation', 'The carrier wave is a:', '["high-frequency radio wave","low-frequency audio wave","sound wave","static field"]'::jsonb, 0, 42),
  ('1f1cad2c-e6d5-4bd6-a817-000000000043'::uuid, 'Modulation', 'The carried wave is a:', '["high-frequency radio wave","low-frequency wave containing the information","microwave","light wave"]'::jsonb, 1, 43),
  ('1f1cad2c-e6d5-4bd6-a817-000000000044'::uuid, 'Modulation', 'In Amplitude Modulation (AM), what changes?', '["the frequency of the carrier","the phase of the carrier","the speed of the carrier","the amplitude of the carrier"]'::jsonb, 3, 44),
  ('1f1cad2c-e6d5-4bd6-a817-000000000045'::uuid, 'Modulation', 'In Frequency Modulation (FM), what changes?', '["the frequency of the carrier","the amplitude of the carrier","the phase of the carrier","nothing"]'::jsonb, 0, 45),
  ('1f1cad2c-e6d5-4bd6-a817-000000000046'::uuid, 'Modulation', 'In Phase Modulation (PM), what changes?', '["the amplitude of the carrier","the frequency of the carrier","the phase of the carrier","the wavelength of the carried wave"]'::jsonb, 2, 46),
  ('1f1cad2c-e6d5-4bd6-a817-000000000047'::uuid, 'Modulation', 'In FM we obtain a modulated wave whose amplitude is:', '["varying and frequency constant","constant and frequency varying","varying and frequency varying","constant and frequency constant"]'::jsonb, 1, 47),
  ('1f1cad2c-e6d5-4bd6-a817-000000000048'::uuid, 'Modulation', 'The purpose of digital modulation is to:', '["increase external effects","increase wave fading","lower the carrier frequency","reduce external effects on the signal and encode it"]'::jsonb, 3, 48),
  ('1f1cad2c-e6d5-4bd6-a817-000000000049'::uuid, 'Modulation', 'In radio broadcasting, the acoustic receiver (microphone):', '["performs frequency modulation","performs amplitude modulation","transforms audible sound into electrical signals with the same frequency","separates audible frequencies from radio frequencies"]'::jsonb, 2, 49),
  ('1f1cad2c-e6d5-4bd6-a817-000000000050'::uuid, 'Range and Propagation of Radio Waves', 'The VLF and LF regions are mainly used in:', '["marine navigation","television","regular radio broadcast","radar"]'::jsonb, 0, 50),
  ('1f1cad2c-e6d5-4bd6-a817-000000000051'::uuid, 'Range and Propagation of Radio Waves', 'The Medium Frequency region (300 kHz – 3 MHz) is mainly used in:', '["marine navigation","air traffic control","police communications","regular radio broadcast"]'::jsonb, 3, 51),
  ('1f1cad2c-e6d5-4bd6-a817-000000000052'::uuid, 'Range and Propagation of Radio Waves', 'The High Frequency region (3 – 30 MHz) is mainly used in:', '["television","some phones and communication between airplanes and ships","marine navigation","regular AM broadcast"]'::jsonb, 1, 52),
  ('1f1cad2c-e6d5-4bd6-a817-000000000053'::uuid, 'Range and Propagation of Radio Waves', 'The Very High Frequency region (30 – 300 MHz) is used in:', '["marine navigation","only communication between ships","television, radio transmitters, air traffic control and police systems","none of these"]'::jsonb, 2, 53),
  ('1f1cad2c-e6d5-4bd6-a817-000000000054'::uuid, 'Range and Propagation of Radio Waves', 'The speed of electromagnetic waves in a medium is given by:', '["v = 1/√(με)","v = √(με)","v = με","v = μ/ε"]'::jsonb, 0, 54),
  ('1f1cad2c-e6d5-4bd6-a817-000000000055'::uuid, 'Range and Propagation of Radio Waves', 'The speed of electromagnetic waves in various media is determined by:', '["the permittivity of the medium only","the inverse of the square root of the product of permittivity and permeability","the sum of permittivity and permeability","the permeability of the medium only"]'::jsonb, 1, 55),
  ('1f1cad2c-e6d5-4bd6-a817-000000000056'::uuid, 'Range and Propagation of Radio Waves', 'Ground waves have frequencies in the range:', '["2 – 30 MHz","above 30 MHz","530 kHz – 2 MHz","3 – 30 kHz"]'::jsonb, 2, 56),
  ('1f1cad2c-e6d5-4bd6-a817-000000000057'::uuid, 'Range and Propagation of Radio Waves', 'The ionosphere reflects radio frequencies in the range:', '["30 – 40 MHz","all radio frequencies","above 20 MHz","2 – 30 MHz"]'::jsonb, 3, 57),
  ('1f1cad2c-e6d5-4bd6-a817-000000000058'::uuid, 'Range and Propagation of Radio Waves', 'Space waves:', '["have frequencies above 30 MHz and pass through the ionosphere","have frequencies of 530 kHz – 2 MHz","are reflected by the ionosphere","bend with the curvature of the Earth"]'::jsonb, 0, 58),
  ('1f1cad2c-e6d5-4bd6-a817-000000000059'::uuid, 'Range and Propagation of Radio Waves', 'The purpose of a communication satellite is to act as:', '["a reflector of ground waves","a repeater that boosts the signal and resends it","an energy generator","a signal absorber"]'::jsonb, 1, 59),
  ('1f1cad2c-e6d5-4bd6-a817-000000000060'::uuid, 'Range and Propagation of Radio Waves', 'Reception of sky waves during the day has a shorter range than at night because of reflection from the:', '["F-layer","space","D-layer (lower region)","ground"]'::jsonb, 2, 60),
  ('1f1cad2c-e6d5-4bd6-a817-000000000061'::uuid, 'Range and Propagation of Radio Waves', 'At night, the ionosphere:', '["loses the F-layer","loses both layers","keeps the D-layer only","loses the D- layer while the F-layer remains"]'::jsonb, 3, 61),
  ('1f1cad2c-e6d5-4bd6-a817-000000000062'::uuid, 'Applications of Electromagnetic Waves', 'The word RADAR stands for:', '["Radio Detection and Ranging","Radar Detection and Range","Radio Direction and Reflection","Radio Wave Ranging"]'::jsonb, 0, 62),
  ('1f1cad2c-e6d5-4bd6-a817-000000000063'::uuid, 'Applications of Electromagnetic Waves', 'The time between transmission and reception of radar waves indicates the target''s:', '["direction","size","range (distance)","colour"]'::jsonb, 2, 63),
  ('1f1cad2c-e6d5-4bd6-a817-000000000064'::uuid, 'Applications of Electromagnetic Waves', 'The direction of the reflected waves in radar indicates the target''s:', '["distance","location","speed","frequency"]'::jsonb, 1, 64),
  ('1f1cad2c-e6d5-4bd6-a817-000000000065'::uuid, 'Applications of Electromagnetic Waves', 'The radar component that reduces the pulse time and sends a high-power pulse to the antenna is the:', '["oscillator","modulator","timer","transmitter"]'::jsonb, 3, 65),
  ('1f1cad2c-e6d5-4bd6-a817-000000000066'::uuid, 'Applications of Electromagnetic Waves', 'The radar signal processor:', '["picks reflected signals from small moving targets and blocks those from large stationary targets","generates a constant-frequency signal","opens and closes the circuit","amplifies the transmitted pulse"]'::jsonb, 0, 66),
  ('1f1cad2c-e6d5-4bd6-a817-000000000067'::uuid, 'Applications of Electromagnetic Waves', 'The radar monitor:', '["amplifies reflected waves","controls the timing","displays reflected waves as bright points","generates the signal"]'::jsonb, 2, 67),
  ('1f1cad2c-e6d5-4bd6-a817-000000000068'::uuid, 'Applications of Electromagnetic Waves', 'The electromagnetic waves used in radar are:', '["ultraviolet","microwaves","X-rays","gamma rays"]'::jsonb, 1, 68),
  ('1f1cad2c-e6d5-4bd6-a817-000000000069'::uuid, 'Applications of Electromagnetic Waves', 'Active remote-sensing images depend on:', '["an energy source installed on the satellite itself","radiation emitted from the target","the Sun only","the Earth''s heat"]'::jsonb, 0, 69),
  ('1f1cad2c-e6d5-4bd6-a817-000000000070'::uuid, 'Applications of Electromagnetic Waves', 'Passive remote-sensing images depend on:', '["an energy source on the satellite","lighting the target","radar pulses","radiation emitted from the target itself"]'::jsonb, 3, 70),
  ('1f1cad2c-e6d5-4bd6-a817-000000000071'::uuid, 'Applications of Electromagnetic Waves', 'Remote sensing by wavelength is divided into:', '["visible, ultraviolet and X-ray images","gamma, X-ray and radio images","visible, infrared and microwave images","active and passive images"]'::jsonb, 2, 71),
  ('1f1cad2c-e6d5-4bd6-a817-000000000072'::uuid, 'Applications of Electromagnetic Waves', 'Satellites equipped with infrared sensors in military applications can:', '["detect only visible light","detect heat emitted from trucks, planes, rockets and persons","work only in clear weather","detect only water"]'::jsonb, 1, 72),
  ('1f1cad2c-e6d5-4bd6-a817-000000000073'::uuid, 'Problems', 'A radio detects a station of 840 kHz using an inductor of 0.04 mH. The required capacitance is approximately:', '["8.97 nF","897 pF","89.7 pF","8.97 μF"]'::jsonb, 1, 73),
  ('1f1cad2c-e6d5-4bd6-a817-000000000074'::uuid, 'Problems', 'The wavelength range covered by an AM station from 540 kHz to 1600 kHz is:', '["55.6 – 160 m","540 – 1600 m","187.5 – 555.6 m","1.875 – 5.556 m"]'::jsonb, 2, 74),
  ('1f1cad2c-e6d5-4bd6-a817-000000000075'::uuid, 'Problems', 'The minimum length of a car antenna to receive a 100 MHz signal is:', '["0.75 m","1.5 m","3 m","0.375 m"]'::jsonb, 0, 75),
  ('1f1cad2c-e6d5-4bd6-a817-000000000076'::uuid, 'Problems', 'The wavelength of electromagnetic waves radiated by a 50 Hz source is:', '["6 m","6×10³ m","6×10⁸ m","6×10⁶ m"]'::jsonb, 3, 76),
  ('1f1cad2c-e6d5-4bd6-a817-000000000077'::uuid, 'Problems', 'The frequency of an electromagnetic wave with wavelength 12 m is:', '["250 MHz","25 MHz","2.5 MHz","250 kHz"]'::jsonb, 1, 77)
)
INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 4, 'Electromagnetic Waves', s.section, 'en', s.question, s.choices, s.answer_index,
       'Chapter 4: Electromagnetic Waves - Multiple Choice Questions (MCQ)', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 4 AND b.language = 'en' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;